/// The named refusal for the Codex kind (gh-760): the Responses adapter
/// has no vision wire. One constant so the two refuse sites (default
/// endpoint pick and the explicit-baseUrl stream route) cannot drift.
StateError _codexVisionRefusal() => StateError(
  'inspect_image: provider kind "chatgpt-codex" (ChatGPT Codex) has no '
  'vision adapter — configure inspect_image with an openai-completions '
  'or copilot vision model',
);

/// Configuration for the [inspectImageTool] vision model.
final class InspectImageConfig {
  /// Creates a configuration.
  const InspectImageConfig({
    required this.modelId,
    required this.apiKey,
    this.baseUrl,
    this.maxTokens = 4096,
    this.providerKind = 'openai-completions',
    this.httpClient,
  });

  /// Vision model id, e.g. `gpt-4o` or `openai/gpt-4o`.
  final String modelId;

  /// API key for the vision provider.
  final String apiKey;

  /// Optional base URL. When omitted the provider's default is used
  /// (OpenAI: https://api.openai.com/v1, Copilot:
  /// https://api.githubcopilot.com).
  final String? baseUrl;

  /// Maximum tokens for the vision description.
  final int maxTokens;

  /// Provider adapter kind. `openai-completions` (OpenAI, OpenRouter, and
  /// any OpenAI-compatible endpoint) and `copilot` (GitHub token exchanged
  /// for the short-lived Copilot API token via [streamCopilot]) are
  /// supported today.
  final String providerKind;

  /// Optional HTTP client for testing.
  final http.Client? httpClient;
}

/// Builds the [Model] descriptor used for the vision call.
Model _visionModel(InspectImageConfig config) {
  final baseUrl =
      config.baseUrl ??
      switch (config.providerKind) {
        'copilot' => copilotIndividualBaseUrl,
        // gh-760: the Codex Responses adapter has no vision wire — refuse
        // with a named error instead of silently misrouting the call to
        // api.openai.com via the catch-all below.
        'chatgpt-codex' => throw _codexVisionRefusal(),
        _ => 'https://api.openai.com/v1',
      };
  return Model(
    id: config.modelId,
    name: config.modelId,
    api: 'openai-completions',
    provider: config.providerKind,
    baseUrl: baseUrl,
    input: const ['text', 'image'],
    contextWindow: 128000,
    maxTokens: config.maxTokens,
  );
}

/// Streams the vision request for [config]'s provider kind. Copilot rides
/// the same SSE completions wire through [streamCopilot] (token exchange +
/// mandatory Copilot headers); every other supported kind speaks plain
/// openai-completions.
AssistantMessageEventStream _streamVisionResponse(
  InspectImageConfig config,
  Model model,
  Context context,
) {
  switch (config.providerKind) {
    case 'openai-completions':
      return streamOpenAICompletions(
        model,
        context,
        OpenAICompletionsOptions(
          apiKey: [REDACTED:Sensitive-Value],
          maxTokens: config.maxTokens,
        ),
        config.httpClient,
      );
    case 'copilot':
      return streamCopilot(
        model,
        context,
        CopilotOptions(githubToken: config.apiKey),
        config.httpClient,
      );
    case 'chatgpt-codex':
      // Named refusal (gh-760): the Codex Responses adapter has no vision
      // wire; reaching the old `default` here meant the call had already
      // been misrouted to api.openai.com by _visionModel.
      throw _codexVisionRefusal();
    default:
      throw StateError(
        'Unsupported inspect_image provider kind: ${config.providerKind}',
      );
  }
}

/// The vision call's outcome: the final text plus the response usage when
/// the provider reported it (the auto-route forwards it to /cost).
typedef _VisionOutcome = ({String text, Usage? usage});

/// Collects the final assistant text out of a vision event stream; throws
/// on a stream error and aborts on [cancelToken] (gh-1984 AC6).
Future<_VisionOutcome> _collectVisionText(
  AssistantMessageEventStream stream,
  CancelToken? cancelToken,
) async {
  String? text;
  String? error;
  Usage? usage;
  await for (final event in stream) {
    cancelToken?.throwIfCancelled();
    if (event is TextDeltaEvent || event is DoneEvent) {
      final message = event.partial;
      final currentText = message.content
          .whereType<TextContent>()
          .map((b) => b.text)
          .join();
      if (currentText.isNotEmpty) text = currentText;
      final messageUsage = message.usage;
      if (messageUsage.totalTokens > 0) {
        usage = messageUsage;
      }
    } else if (event is ErrorEvent) {
      error = event.error.errorMessage ?? 'unknown error';
    }
  }

  if (error != null) {
    throw StateError('Vision model error: $error');
  }
  return (text: text?.trim() ?? '', usage: usage);
}

/// One vision-model request over [bytes]: the system prompt + the image +
/// [userPrompt], streamed through [config]'s provider kind. Returns the
/// final assistant text. Shared by the `inspect_image` tool and the read
/// auto-route (gh-1984 AC2) so both describe images through the SAME
/// request shape.
///
/// [cancelToken] aborts the stream mid-flight (AC6); [onUsage] receives
/// the response's usage so hosts can surface the spend in /cost. Throws
/// on a stream error — callers degrade to their own failure notes.
Future<String> describeImageWithVisionModel(
  InspectImageConfig config,
  Uint8List bytes,
  String mimeType,
  String userPrompt, {
  CancelToken? cancelToken,
  void Function(Usage usage)? onUsage,
}) async {
  cancelToken?.throwIfCancelled();
  final model = _visionModel(config);
  final image = ImageContent(data: base64Encode(bytes), mimeType: mimeType);
  final context = Context(
    systemPrompt: inspectImageVisionSystemPrompt,
    messages: [
      UserMessage(
        content: [
          TextContent(
            text: userPrompt.isEmpty ? 'Describe this image.' : userPrompt,
          ),
          image,
        ],
        timestamp: DateTime.now(),
      ),
    ],
  );

  final stream = _streamVisionResponse(config, model, context);
  final result = await _collectVisionText(stream, cancelToken);
  if (result.usage != null) onUsage?.call(result.usage!);
  return result.text;
}

/// Creates the `inspect_image` tool.
///
/// Parameters:
/// - `path` (string, required): path to the image file.
/// - `prompt` (string, optional): specific question or instructions.
///
/// [onUsage] receives the vision call's response usage (gh-1984 review
/// thread 7) so the tool's spend is as visible in /cost as the read
/// auto-route's; hosts without a sink leave it unset (untracked).
AgentTool inspectImageTool(
  ExecutionEnv env,
  InspectImageConfig config, {
  void Function(Usage usage)? onUsage,
}) {
  return AgentTool(
    name: 'inspect_image',
    label: 'inspect_image',
    tier: ApprovalTier.read,
    description:
        'Analyze a local image file using a dedicated vision-capable model. '
        'Returns a text description; the image itself does not enter the main '
        'chat context. Supported formats: PNG, JPEG, GIF, WebP, BMP.',
    parameters: const {
      'type': 'object',
      'properties': {
        'path': {
          'type': 'string',
          'description': 'Path to the image file (relative or absolute)',
        },
        'prompt': {
          'type': 'string',
          'description': 'Optional specific question or instructions',
        },
      },
      'required': ['path'],
    },
    execute: (arguments, cancelToken, onUpdate) async {
      cancelToken?.throwIfCancelled();
      final path = arguments['path'] as String;
      final prompt = (arguments['prompt'] as String?) ?? '';

      final read = await env.readBinaryFile(path);
      if (read.isErr) {
        throw StateError('${read.errorOrNull}');
      }
      final bytes = read.valueOrNull!;
      cancelToken?.throwIfCancelled();

      // Detect MIME type from magic bytes. Only the supported image formats
      // are accepted; the actual vision request will re-encode/rescale if
      // needed on the provider side.
      final mimeType = _detectImageMimeType(bytes);
      if (mimeType == null) {
        throw StateError('Unsupported image format or not an image: $path');
      }

      // The shared vision helper direct (gh-1984 review thread 7): the
      // cancel token aborts a hung vision stream MID-FLIGHT (not only the
      // pre-call checkpoints), and the tool's spend rides onUsage like the
      // auto-route's. The pass-through wrapper that dropped both is gone.
      final description = await describeImageWithVisionModel(
        config,
        bytes,
        mimeType,
        prompt,
        cancelToken: cancelToken,
        onUsage: onUsage,
      );
      return ToolExecutionResult(content: [TextContent(text: description)]);
    },
  );
}

/// Magic-byte signatures of the image formats the tool claims to support,
/// checked in order.
const _imageMagicSignatures = [
  ('image/png', <int>[0x89, 0x50]),
  ('image/jpeg', <int>[0xFF, 0xD8]),
  ('image/gif', <int>[0x47, 0x49, 0x46]),
  ('image/webp', <int>[0x52, 0x49]), // RIFF
  ('image/bmp', <int>[0x42, 0x4D]),
];

/// Whether [bytes] starts with the [magic] signature.
bool _matchesMagicBytes(Uint8List bytes, List<int> magic) {
  for (var i = 0; i < magic.length; i++) {
    if (bytes[i] != magic[i]) return false;
  }
  return true;
}

/// Minimal MIME detection for the image formats the tool claims to support.
String? _detectImageMimeType(Uint8List bytes) {
  if (bytes.length < 8) return null;
  for (final (mimeType, magic) in _imageMagicSignatures) {
    if (_matchesMagicBytes(bytes, magic)) return mimeType;
  }
  return null;
}

/// Inline-image pipeline for the `read` tool (pi's `utils/image-process.ts`): format normalization, EXIF baking, and the PNG-then-JPEG byte-budget shrink ladder ([_processImage], [_resizeInlineImage]). Split out of `builtin_tools.dart` to keep that file under the repo line gate; same library (a `part of`), so the privates stay visible.
part of 'builtin_tools.dart';

// ---------------------------------------------------------------------------
// Image handling for the read tool
// ---------------------------------------------------------------------------

/// Maximum width/height for inline images (pi's `maxWidth`/`maxHeight`).
const _defaultImageMaxDimension = 2000;

/// Base64 payload budget for inline images: 4.5MB of base64 (== `4.5 * 1024 *
/// 1024`), providing headroom below Anthropic's 5MB inline limit (pi's
/// `DEFAULT_MAX_BYTES`).
const _defaultImageMaxBase64Bytes = 4718592;

/// JPEG quality ladder tried after PNG at each size step (pi's `qualitySteps`
/// with the default `jpegQuality` 80).
const _imageJpegQualitySteps = [80, 85, 70, 55, 40];

const _supportedImageFormats = {
  ImageFormat.png,
  ImageFormat.jpg,
  ImageFormat.gif,
  ImageFormat.webp,
  ImageFormat.bmp,
};

/// Formats providers accept inline; other decodable formats (BMP) are
/// converted first (pi's `normalizeSupportedImageMimeType`).
const _inlineImageFormats = {
  ImageFormat.png,
  ImageFormat.jpg,
  ImageFormat.gif,
  ImageFormat.webp,
};

String? _mimeTypeForImageFormat(ImageFormat format) {
  return switch (format) {
    ImageFormat.png => 'image/png',
    ImageFormat.jpg => 'image/jpeg',
    ImageFormat.gif => 'image/gif',
    ImageFormat.webp => 'image/webp',
    ImageFormat.bmp => 'image/bmp',
    _ => null,
  };
}

/// Encoded size of [bytes] as base64 text (pi compares the UTF-8 byte length
/// of the base64 string, which equals its character length).
int _base64Length(Uint8List bytes) => ((bytes.length + 2) ~/ 3) * 4;

/// The outcome of the inline-image pipeline ([_processImage] /
/// [_resizeInlineImage]): the base64 payload to send, the ORIGINAL
/// dimensions, and the dimensions it is actually displayed at.
typedef _InlineImageResult = ({
  String mimeType,
  String base64,
  int width,
  int height,
  bool resized,
  int outputWidth,
  int outputHeight,
  String? convertedFrom,
});

_InlineImageResult _processImage(
  Uint8List bytes,
  ImageFormat format, {
  int maxDimension = _defaultImageMaxDimension,
  int maxBase64Bytes = _defaultImageMaxBase64Bytes,
}) {
  // Normalize (pi's `normalizeImage`): formats providers do not accept inline
  // (BMP) decode and convert to PNG first; EXIF orientation is baked in.
  var inputBytes = bytes;
  var inputFormat = format;
  String? convertedFrom;
  if (!_inlineImageFormats.contains(format)) {
    final source = _decodeOrThrow(bytes);
    inputBytes = encodePng(bakeOrientation(source));
    inputFormat = ImageFormat.png;
    convertedFrom = _mimeTypeForImageFormat(format);
  }
  return _resizeInlineImage(
    inputBytes,
    inputFormat,
    convertedFrom: convertedFrom,
    maxDimension: maxDimension,
    maxBase64Bytes: maxBase64Bytes,
  );
}

/// Fits an inline-format image within the dimension and base64 byte limits.
///
/// Ported from pi's `resizeImageInProcess` (`utils/image-resize-core.ts`):
/// EXIF orientation is baked before measuring; images already within ALL
/// limits pass through with their ORIGINAL bytes untouched; otherwise each
/// size step tries PNG, then JPEG at decreasing quality
/// ([_imageJpegQualitySteps]), shrinking dimensions by 0.75 until a candidate
/// fits the byte budget.
_InlineImageResult _resizeInlineImage(
  Uint8List bytes,
  ImageFormat format, {
  required String? convertedFrom,
  required int maxDimension,
  required int maxBase64Bytes,
}) {
  final decoded = _decodeOrThrow(bytes);
  // Bake EXIF orientation before measuring/resizing so the model sees the
  // image as displayed (pi's `applyExifOrientation`).
  final image = _bakeExifOrientation(decoded);
  final width = image.width;
  final height = image.height;

  // Pass-through: within the dimension AND byte limits, keep the original
  // bytes untouched (no re-encode).
  if (width <= maxDimension &&
      height <= maxDimension &&
      _base64Length(bytes) < maxBase64Bytes) {
    return (
      mimeType: _mimeTypeForImageFormat(format) ?? 'image/png',
      base64: base64Encode(bytes),
      width: width,
      height: height,
      resized: false,
      outputWidth: width,
      outputHeight: height,
      convertedFrom: convertedFrom,
    );
  }

  final (:targetWidth, :targetHeight) = _clampToMaxDimension(
    width,
    height,
    maxDimension,
  );

  final fitted = _shrinkInlineImageToFit(
    image,
    width,
    height,
    targetWidth,
    targetHeight,
    maxBase64Bytes,
    convertedFrom,
  );
  if (fitted != null) return fitted;

  throw StateError('Could not resize image below the inline image size limit');
}

/// The shrink loop of [_resizeInlineImage]: tries [_fitImageAtSize] at the
/// current size, then shrinks dimensions by 0.75 and retries, until a
/// candidate fits the byte budget. Returns null when the shrink stalls (see
/// [shrinkStepStalls]) so the caller can fail with pi's error.
_InlineImageResult? _shrinkInlineImageToFit(
  Image image,
  int width,
  int height,
  int targetWidth,
  int targetHeight,
  int maxBase64Bytes,
  String? convertedFrom,
) {
  var currentWidth = targetWidth;
  var currentHeight = targetHeight;
  while (true) {
    final fitted = _fitImageAtSize(
      image,
      width,
      height,
      currentWidth,
      currentHeight,
      maxBase64Bytes,
      convertedFrom,
    );
    if (fitted != null) return fitted;

    final (nextWidth, nextHeight) = nextShrinkStep(currentWidth, currentHeight);
    if (shrinkStepStalls(currentWidth, currentHeight, nextWidth, nextHeight)) {
      return null;
    }
    currentWidth = nextWidth;
    currentHeight = nextHeight;
  }
}

/// One 0.75 shrink step of the inline-image shrink loop (a dimension already
/// at 1 stays there).
(int, int) nextShrinkStep(int width, int height) =>
    (width == 1 ? 1 : width * 3 ~/ 4, height == 1 ? 1 : height * 3 ~/ 4);

/// The shrink loop's safety valves: the step stalls at 1x1 or when the 0.75
/// shrink stops making progress. Unreachable via the public API with default
/// limits — even a maximal source clamps to [_defaultImageMaxDimension] and
/// fits the byte budget long before the step stalls.
bool shrinkStepStalls(
  int currentWidth,
  int currentHeight,
  int nextWidth,
  int nextHeight,
) {
  return (currentWidth == 1 && currentHeight == 1) ||
      (nextWidth == currentWidth && nextHeight == currentHeight);
}

/// Decodes [bytes], throwing when the image library cannot make sense of
/// them (a valid signature with a garbage payload).
Image _decodeOrThrow(Uint8List bytes) {
  final decoded = decodeImage(bytes);
  if (decoded == null) {
    throw StateError('Could not decode image');
  }
  return decoded;
}

/// Bakes EXIF orientation into the pixels when the tag says the stored image
/// is rotated/flipped (pi's `applyExifOrientation`); otherwise returns
/// [decoded] untouched.
Image _bakeExifOrientation(Image decoded) {
  return decoded.exif.imageIfd.hasOrientation &&
          decoded.exif.imageIfd.orientation != 1
      ? bakeOrientation(decoded)
      : decoded;
}

/// The initial resize target: the original dimensions when already within
/// [maxDimension], else the aspect-preserving clamp to it (pi's
/// `targetWidth`/`targetHeight`).
({int targetWidth, int targetHeight}) _clampToMaxDimension(
  int width,
  int height,
  int maxDimension,
) {
  var targetWidth = width;
  var targetHeight = height;
  if (width > maxDimension || height > maxDimension) {
    if (width >= height) {
      targetWidth = maxDimension;
      targetHeight = (height * maxDimension / width).round();
    } else {
      targetHeight = maxDimension;
      targetWidth = (width * maxDimension / height).round();
    }
  }
  return (targetWidth: targetWidth, targetHeight: targetHeight);
}

/// Tries one size step: PNG first, then JPEG at decreasing quality
/// ([_imageJpegQualitySteps]); returns null when no candidate fits the byte
/// budget, so the caller shrinks and retries.
_InlineImageResult? _fitImageAtSize(
  Image image,
  int width,
  int height,
  int currentWidth,
  int currentHeight,
  int maxBase64Bytes,
  String? convertedFrom,
) {
  final candidate = currentWidth == width && currentHeight == height
      ? image
      : copyResize(
          image,
          width: currentWidth,
          height: currentHeight,
          interpolation: Interpolation.cubic,
        );
  final png = encodePng(candidate);
  if (_base64Length(png) < maxBase64Bytes) {
    return (
      mimeType: 'image/png',
      base64: base64Encode(png),
      width: width,
      height: height,
      resized: true,
      outputWidth: currentWidth,
      outputHeight: currentHeight,
      convertedFrom: convertedFrom,
    );
  }
  String? jpegBase64;
  for (final quality in _imageJpegQualitySteps) {
    final jpeg = encodeJpg(candidate, quality: quality);
    if (_base64Length(jpeg) < maxBase64Bytes) {
      jpegBase64 = base64Encode(jpeg);
      break;
    }
  }
  if (jpegBase64 != null) {
    return (
      mimeType: 'image/jpeg',
      base64: jpegBase64,
      width: width,
      height: height,
      resized: true,
      outputWidth: currentWidth,
      outputHeight: currentHeight,
      convertedFrom: convertedFrom,
    );
  }
  return null;
}

ImageFormat? _detectImageFormat(Uint8List bytes) {
  if (bytes.isEmpty) return null;
  try {
    return findFormatForData(bytes);
  } on Object {
    return null;
  }
}

