String _normalizeToolCallId(String id, Model model) {
  // Handle pipe-separated IDs from OpenAI Responses API
  // (format: {call_id}|{id}): extract the call_id part, sanitize to
  // allowed chars, and truncate to 40 chars (OpenAI limit).
  if (id.contains('|')) {
    final callId = id.split('|').first;
    return _truncate40(callId.replaceAll(RegExp('[^a-zA-Z0-9_-]'), '_'));
  }
  if (model.provider == 'openai') {
    // LiteLLM front-ends (e.g. CodeMie) embed Gemini thought signatures in
    // the tool call id as `call_<n>__thought__<base64>` and recover them
    // from the echoed id; truncating destroys the signature and Vertex then
    // rejects the replay with a thought_signature base64 400.
    if (id.contains('__thought__')) {
      return id;
    }
    return _truncate40(id);
  }
  return id;
}

/// Audio MIME type → OpenAI `input_audio.format` tag. mp3/wav are the
/// OpenAI-documented ones; OpenRouter's Gemini route additionally accepts
/// m4a/aac/flac/ogg (verified against AIIN). Unknown mime types fall back
/// to `mp3` — a table keeps the lookup O(1) and the complexity gate green
/// (a 13-case switch measured CRAP 21.91 against the 12.0 ratchet).
const _openAiAudioFormats = <String, String>{
  'audio/mpeg': 'mp3',
  'audio/mp3': 'mp3',
  'audio/wav': 'wav',
  'audio/x-wav': 'wav',
  'audio/mp4': 'm4a',
  'audio/x-m4a': 'm4a',
  'audio/m4a': 'm4a',
  'audio/aac': 'aac',
  'audio/x-aac': 'aac',
  'audio/flac': 'flac',
  'audio/ogg': 'ogg',
};

String _openAiAudioFormat(String mimeType) =>
    _openAiAudioFormats[mimeType.toLowerCase()] ?? 'mp3';

Map<String, dynamic>? _convertUserMessage(UserMessage message) {
  final content = message.content;
  if (content is String) {
    return {'role': 'user', 'content': content};
  }
  final parts = <Map<String, dynamic>>[];
  for (final item in content as List<ContentBlock>) {
    switch (item) {
      case TextContent():
        parts.add({'type': 'text', 'text': item.text});
      case ImageContent():
        parts.add({
          'type': 'image_url',
          'image_url': {'url': 'data:${item.mimeType};base64,${item.data}'},
        });
      case AudioContent():
        // OpenAI/OpenRouter audio input (AIIN routes Gemini through this
        // dialect too). Senders attach audio only for audio-capable
        // models; mime type reduces to the wire `format` tag.
        parts.add({
          'type': 'input_audio',
          'input_audio': {
            'data': item.data,
            'format': _openAiAudioFormat(item.mimeType),
          },
        });
      case ThinkingContent() || ToolCall():
        // Not valid in user messages; skip defensively.
        break;
    }
  }
  if (parts.isEmpty) {
    return null;
  }
  return {'role': 'user', 'content': parts};
}

Map<String, dynamic>? _convertAssistantMessage(
  AssistantMessage message,
  Model model,
) {
  final assistantMsg = <String, dynamic>{'role': 'assistant'};

  _applyAssistantContent(assistantMsg, message.content);
  _applyAssistantToolCalls(assistantMsg, message.content, model);

  // Skip assistant messages that have no content and no tool calls.
  final hasContent =
      assistantMsg['content'] is String &&
      (assistantMsg['content'] as String).isNotEmpty;
  if (!hasContent && !assistantMsg.containsKey('tool_calls')) {
    return null;
  }
  return assistantMsg;
}

void _applyAssistantContent(
  Map<String, dynamic> assistantMsg,
  List<ContentBlock> content,
) {
  final assistantText = _assistantText(content);
  final thinkingBlocks = _thinkingBlocks(content);
  if (thinkingBlocks.isNotEmpty) {
    // Always send assistant content as a plain string (OpenAI Chat
    // Completions API standard format); see pi for why arrays of text
    // parts break some models.
    if (assistantText.isNotEmpty) {
      assistantMsg['content'] = assistantText;
    }
    // Use the signature from the first thinking block if available (for
    // llama.cpp server + gpt-oss).
    final signature = thinkingBlocks.first.thinkingSignature;
    if (signature != null && signature.isNotEmpty) {
      assistantMsg[signature] = thinkingBlocks
          .map((block) => block.thinking)
          .join('\n');
    }
  } else if (assistantText.isNotEmpty) {
    assistantMsg['content'] = assistantText;
  }
}

String _assistantText(List<ContentBlock> content) {
  return [
    for (final block in content)
      if (block is TextContent && block.text.trim().isNotEmpty) block.text,
  ].join();
}

List<ThinkingContent> _thinkingBlocks(List<ContentBlock> content) {
  return [
    for (final block in content)
      if (block is ThinkingContent && block.thinking.trim().isNotEmpty) block,
  ];
}

/// Converts internal messages to Gemini `Content[]` format.
///
/// Ported from pi's `convertMessages`. The image-downgrade half of pi's
/// `transformMessages` pre-pass runs first via [downgradeUnsupportedImages];
/// the tool-call-id normalization half still happens at conversion time.
List<Map<String, dynamic>> _convertMessages(Model model, Context context) {
  final contents = <Map<String, dynamic>>[];
  final includeId = _requiresToolCallId(model.id);

  for (final message in downgradeUnsupportedImages(context.messages, model)) {
    if (message is UserMessage) {
      final content = _convertUserMessage(message);
      if (content != null) {
        contents.add(content);
      }
    } else if (message is AssistantMessage) {
      final content = _convertAssistantMessage(message, model, includeId);
      if (content != null) {
        contents.add(content);
      }
    } else if (message is ToolResultMessage) {
      _appendToolResultMessage(contents, message, model, includeId);
    }
  }

  return contents;
}

/// Converts a user message to a Gemini user `Content`, or null when it has
/// no convertible parts. Ported from pi's `convertMessages` user branch.
Map<String, dynamic>? _convertUserMessage(UserMessage message) {
  final content = message.content;
  if (content is String) {
    return {
      'role': 'user',
      'parts': [
        {'text': content},
      ],
    };
  }
  final parts = <Map<String, dynamic>>[];
  for (final item in content as List<ContentBlock>) {
    switch (item) {
      case TextContent():
        parts.add({'text': item.text});
      case ImageContent():
        parts.add(_convertImageContent(item));
      case AudioContent():
        // Gemini audio understanding: raw bytes ride inlineData exactly
        // like images (mp3, mp4/m4a, wav, aac, flac, ogg mime types).
        parts.add({
          'inlineData': {'mimeType': item.mimeType, 'data': item.data},
        });
      case ThinkingContent() || ToolCall():
        // Not valid in user messages; skip defensively.
        break;
    }
  }
  if (parts.isEmpty) {
    return null;
  }
  return {'role': 'user', 'parts': parts};
}

/// Converts an assistant message to a Gemini model `Content`, or null when
/// it has no convertible parts. Ported from pi's `convertMessages` assistant
/// branch.
Map<String, dynamic>? _convertAssistantMessage(
  AssistantMessage message,
  Model model,
  bool includeId,
) {
  final parts = <Map<String, dynamic>>[];
  // Only keep thinking blocks/signatures when the message is from the
  // same provider and model.
  final isSameProviderAndModel =
      message.provider == model.provider && message.model == model.id;

  for (final block in message.content) {
    final part = _convertAssistantBlock(
      block,
      isSameProviderAndModel,
      includeId,
    );
    if (part != null) {
      parts.add(part);
    }
  }

  if (parts.isEmpty) {
    return null;
  }
  return {'role': 'model', 'parts': parts};
}

/// Converts one assistant content block to a Gemini part, or null when the
/// block is skipped (empty text/thinking, invalid image). Ported from pi's
/// `convertMessages` assistant-block switch.
Map<String, dynamic>? _convertAssistantBlock(
  ContentBlock block,
  bool isSameProviderAndModel,
  bool includeId,
) {
  return switch (block) {
    TextContent() => _convertAssistantTextBlock(block, isSameProviderAndModel),
    ThinkingContent() => _convertAssistantThinkingBlock(
      block,
      isSameProviderAndModel,
    ),
    ToolCall() => _convertAssistantToolCallBlock(
      block,
      isSameProviderAndModel,
      includeId,
    ),
    // Not valid in assistant messages; skip defensively.
    ImageContent() || AudioContent() => null,
  };
}

/// Ported from pi's assistant-block `TextContent` case.
Map<String, dynamic>? _convertAssistantTextBlock(
  TextContent block,
  bool isSameProviderAndModel,
) {
  final thoughtSignature = _resolveThoughtSignature(
    isSameProviderAndModel,
    block.textSignature,
  );
  // Skip empty text blocks — unless they carry a thought signature. Gemini
  // can attach the signature to a part whose visible text is empty and
  // requires it echoed back; dropping it breaks the reasoning chain and the
  // next request fails with the 400 'missing a thought_signature' on the
  // replayed functionCall (pi keeps such parts for the same reason).
  if (block.text.trim().isEmpty && thoughtSignature == null) {
    return null;
  }
  return {'text': block.text, 'thoughtSignature': ?thoughtSignature};
}

/// Ported from pi's assistant-block `ThinkingContent` case.
Map<String, dynamic>? _convertAssistantThinkingBlock(
  ThinkingContent block,
  bool isSameProviderAndModel,
) {
  if (isSameProviderAndModel) {
    final thoughtSignature = _resolveThoughtSignature(
      isSameProviderAndModel,
      block.thinkingSignature,
    );
    // Same rule as text blocks: an empty thinking block is dropped only
    // when it carries no signature — Gemini needs signature-bearing parts
    // echoed back verbatim (see _convertAssistantTextBlock).
    if (block.thinking.trim().isEmpty && thoughtSignature == null) {
      return null;
    }
    return {
      'thought': true,
      'text': block.thinking,
      'thoughtSignature': ?thoughtSignature,
    };
  }
  // Other provider/model: convert to plain text (no tags to
  // avoid the model mimicking them).
  return {'text': block.thinking};
}

/// Ported from pi's assistant-block `ToolCall` case.
Map<String, dynamic> _convertAssistantToolCallBlock(
  ToolCall block,
  bool isSameProviderAndModel,
  bool includeId,
) {
  final thoughtSignature = _resolveThoughtSignature(
    isSameProviderAndModel,
    block.thoughtSignature,
  );
  return {
    'functionCall': {
      'name': block.name,
      'args': block.arguments,

125:  /// How thinking content is returned: `summarized` (default) or `omitted`.
202:/// `http.testing.MockClient`); when omitted, an owned client is created and
808:/// provider default (omitted). [ladderBudget] is the budget computed in
829:      // the thinking block is omitted entirely instead (never invalid;

  final blocks = <Map<String, dynamic>>[];
  for (final block in content) {
    switch (block) {
      case TextContent():
        blocks.add({'type': 'text', 'text': block.text});
      case ImageContent():
        blocks.add({
          'type': 'image',
          'source': {
            'type': 'base64',
            'media_type': block.mimeType,
            'data': block.data,
          },
        });
      case ThinkingContent() || ToolCall() || AudioContent():
        // Not valid in tool results; skip defensively.
        break;
    }
  }
  if (!blocks.any((block) => block['type'] == 'text')) {
    blocks.insert(0, {'type': 'text', 'text': '(see attached image)'});
  }
  return blocks;
