      onImageUsage: onImageUsage,
      mediaFileReadNotes: mediaFileReadNotes,
      transcribeAvailable: transcribeAvailable,
    ),
    writeFileTool(env),
    editFileTool(env, snapshots: store),
    listDirTool(env),
