const openRouter = new OpenRouter({
  apiKey: '[REDACTED:Sensitive-Value]',
});

const result = await openRouter.chat.send({
  chatRequest: {
    model: "{{MODEL}}",
    messages: [
      {
        role: "user",
        content: [
          {
            type: "text",
            text: "Please describe what's happening in this video.",
          },
          {
            type: "video_url",
