    if (!blocks.any((block) => block is VideoContent)) return blocks;
    changed = true;
    return [
      for (final block in blocks)
        if (block is VideoContent)
          TextContent(text: nonVisionUserVideoPlaceholder)
        else
          block,
    ];
  }

  final out = <Message>[];
  for (final message in messages) {
    if (message is UserMessage && message.content is List<ContentBlock>) {
      final blocks = stripBlocks(message.content as List<ContentBlock>);
      if (!identical(blocks, message.content)) {
        out.add(
          UserMessage(content: blocks, timestamp: message.timestamp),
        );
        continue;
      }
    } else if (message is ToolResultMessage) {
      final blocks = stripBlocks(message.content);
      if (!identical(blocks, message.content)) {
        out.add(
          ToolResultMessage(
            toolCallId: message.toolCallId,
            toolName: message.toolName,
            content: [
              for (final block in blocks)
