      return http.StreamedResponse(
        Stream.fromIterable(['data: $payload\n\n', 'data: $done\n\n']).transform(utf8.encoder),
        200, headers: {'content-type': 'text/event-stream'});
    });
    final config = InspectImageConfig(modelId: 'gpt-4o', apiKey: '[REDACTED:Sensitive-Value]', maxImagesPerCall: 1, httpClient: client);
