  for (final (dx, dy) in on) {
    // The glyph sits on a black plate [stitchPlatePadding] px inside
    // the tile corner (the placement [stitchTiles] guarantees).
    final pixel = composite.getPixel(
      origin.$1 + stitchPlatePadding + dx,
