No existing tests touch payloadCariesImageBytes directly. I'll add a small focused test file for the AC7 registry mechanics: `test/agent/image_registry_video_test.dart`:
1. video payloads count toward payloadCariesImageBytes;
2. stripAllOriginalMedia removes videos (returns null registry);
3. text-only payload stays false;
4. carriesImageBytes (public) true when video present.

arguments.content:
import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

DateTime _ts() => DateTime.utc(2026);

ToolResultMessage _videoResult(String id, {required bool withVideo}) =>
    ToolResultMessage(
      toolCallId: id,
      toolName: 'read',
      isError: false,
      content: [
        const TextContent(text: '[Video: clip.mp4]'),
        if (withVideo)
          const VideoContent(data: 'aGk=', mimeType: 'video/mp4'),
      ],
      timestamp: _ts(),
    );

void main() {
  test('AC7 — a video payload registers a live registry whose snapshot '
      'keeps the video block', () {
    final registry = SessionImageRegistry.fromPayload([
      UserMessage.text('read it', timestamp: _ts()),
      _videoResult('call_1', withVideo: true),
    ]);
    expect(registry, isNotNull);
    expect(payloadCarriesImageBytes(registry!.snapshot()), isTrue);
    expect(registry.liveCount, 0); // videos are not pooled (images only)
    final snapshot = registry.snapshot();
    final toolResult = snapshot.whereType<ToolResultMessage>().single;
    expect(toolResult.content.whereType<VideoContent>(), hasLength(1));
  });

  test('AC7 — carriesImageBytes sees video-only payloads', () {
    final context = Context(messages: [
      UserMessage(
        content: const [VideoContent(data: 'aGk=', mimeType: 'video/mp4')],
        timestamp: _ts(),
      ),
    ]);
    expect(payloadCarriesImageBytes(context.messages), isTrue);
    expect(carriesImageBytes(context), isTrue);
  });

  test('text-only payloads still report no image bytes', () {
    final context = Context(messages: [
      UserMessage.text('plain', timestamp: _ts()),
      _videoResult('call_2', withVideo: false),
    ]);
    expect(payloadCarriesImageBytes(context.messages), isFalse);
  });

  test('stripAllOriginalMedia strips videos AND images — the payload that '
      'comes back has neither, and pool images stay in the registry', () {
    final registry = SessionImageRegistry.fromPayload([
      UserMessage(
        content: const [
          ImageContent(data: 'aW1n', mimeType: 'image/png'),
        ],
        timestamp: _ts(),
      ),
      _videoResult('call_3', withVideo: true),
    ]);
    final stripped = stripAllOriginalMedia(registry!.snapshot(), registry);
    expect(payloadCarriesImageBytes(stripped), isFalse);
    // the pooled user image survives the strip
    expect(
      stripped.whereType<UserMessage>().any(
            (message) => message.content.whereType<ImageContent>().isNotEmpty,
          ),
      isTrue,
    );
    expect(
      stripped.whereType<ToolResultMessage>().any(
            (message) => message.content.whereType<VideoContent>().isNotEmpty,
          ),
      isFalse,
    );
  });
}

